//! Reader mode over its corpus (`fixtures/reflow/`, generated by `laminapdf-build`'s tests):
//! each tagged file comes out as its JSON lists it, in the tree's order though drawn in reverse,
//! with a table as one crop; each file with a broken tree is refused for the reason its JSON
//! names; the mixed file's figure, formula and table are crops with their `/Alt`, never text.
#![allow(clippy::unwrap_used, clippy::panic, clippy::indexing_slicing, reason = "test code")]

use laminapdf_extract::{Reflow, ReflowKind, reflow};
use laminapdf_model::{Document, OpenOptions};
use laminapdf_syntax::CancelToken;
use serde_json::Value;

fn dir() -> std::path::PathBuf {
    laminapdf_test_fixtures::fixtures_dir().join("reflow")
}

fn read(name: &str) -> (Reflow, Value) {
    let bytes = std::fs::read(dir().join(format!("{name}.pdf"))).unwrap();
    let expected = serde_json::from_slice(&std::fs::read(dir().join(format!("{name}.json"))).unwrap()).unwrap();
    let doc = Document::open(bytes, OpenOptions::default()).unwrap();
    (reflow(&doc, &CancelToken::new()).unwrap(), expected)
}

fn names() -> Vec<String> {
    let mut names: Vec<String> = std::fs::read_dir(dir())
        .unwrap()
        .filter_map(|e| {
            let name = e.unwrap().file_name().to_string_lossy().into_owned();
            name.strip_suffix(".pdf").map(str::to_owned)
        })
        .collect();
    names.sort();
    names
}

/// The JSON's name for a block's kind.
fn kind(kind: &ReflowKind) -> &'static str {
    match kind {
        ReflowKind::Heading { .. } => "heading",
        ReflowKind::Paragraph => "paragraph",
        ReflowKind::ListItem { .. } => "list-item",
        ReflowKind::Quote => "quote",
        ReflowKind::Caption => "caption",
        ReflowKind::Note => "footnote",
        ReflowKind::Figure => "figure",
        ReflowKind::Formula => "formula",
        ReflowKind::Table => "table",
        _ => "other",
    }
}

/// `s` without its white space: extraction joins a CJK block's lines with a space.
fn squeeze(s: &str) -> String {
    s.chars().filter(|c| !c.is_whitespace()).collect()
}

/// A file's expected blocks as (kind, text or alt), a table's cells as one table.
fn expected_blocks(expected: &Value) -> Vec<(String, String)> {
    let mut out: Vec<(String, String)> = Vec::new();
    for block in expected["blocks"].as_array().unwrap() {
        let kind = block["kind"].as_str().unwrap();
        if kind == "table-cell" {
            if out.last().is_none_or(|(k, _)| k != "table") {
                out.push(("table".to_owned(), String::new()));
            }
            continue;
        }
        let text = block["text"]
            .as_str()
            .or_else(|| block["alt"].as_str())
            .unwrap_or_default();
        out.push((kind.to_owned(), squeeze(text)));
    }
    out
}

#[test]
fn every_tagged_file_reads_in_its_trees_order_and_every_broken_tree_is_refused() {
    let mut failures = Vec::new();
    for name in names() {
        let (got, expected) = read(&name);
        if expected["available"] == false {
            let reason = got.reason.map(laminapdf_extract::ReflowRefusal::as_str);
            if got.available || reason != expected["reason"].as_str() {
                failures.push(format!(
                    "{name}: refused for {reason:?}, expected {}",
                    expected["reason"]
                ));
            }
            continue;
        }
        let blocks: Vec<(String, String)> = got
            .blocks
            .iter()
            .map(|b| {
                let text = if b.kind.is_crop() {
                    b.alt.clone().unwrap_or_default()
                } else {
                    b.text.clone()
                };
                (kind(&b.kind).to_owned(), squeeze(&text))
            })
            .collect();
        if !got.available || blocks != expected_blocks(&expected) {
            failures.push(format!("{name}: {:?} {blocks:?}", got.reason));
        }
    }
    assert!(failures.is_empty(), "{failures:#?}");
}

#[test]
fn the_figure_is_cropped_to_what_it_paints_and_nothing_inside_a_crop_is_text() {
    let (got, _) = read("mixed");
    let figure = got.blocks.iter().find(|b| b.kind == ReflowKind::Figure).unwrap();
    let bbox = figure.bbox.unwrap();
    let got_box = [bbox.x0.get(), bbox.y0.get(), bbox.x1.get(), bbox.y1.get()];
    let want = [56.0, 180.0, 216.0, 290.0];
    assert!(
        got_box.iter().zip(want).all(|(a, b)| (a - b).abs() < 0.5),
        "{got_box:?}"
    );
    // The formula's "E = mc2" and the table's numbers are in crops, never in the text.
    let text: String = got.blocks.iter().map(|b| b.text.as_str()).collect();
    assert!(!text.contains("mc2") && !text.contains("34"), "{text}");
    let formula = got.blocks.iter().find(|b| b.kind == ReflowKind::Formula).unwrap();
    assert!(formula.bbox.is_some_and(|b| b.width().get() > 10.0));
}

#[test]
fn the_tagged_report_golden_keeps_its_caption_and_list_as_text() {
    let bytes = std::fs::read(laminapdf_test_fixtures::fixtures_dir().join("golden/tagged-report.pdf")).unwrap();
    let doc = Document::open(bytes, OpenOptions::default()).unwrap();
    let got = reflow(&doc, &CancelToken::new()).unwrap();
    assert!(got.available, "{:?} {:?}", got.reason, got.checks);
    let kinds: Vec<&str> = got.blocks.iter().map(|b| kind(&b.kind)).collect();
    for wanted in ["heading", "figure", "caption", "table", "list-item"] {
        assert!(kinds.contains(&wanted), "{kinds:?}");
    }
    let figure = got.blocks.iter().find(|b| b.kind == ReflowKind::Figure).unwrap();
    assert!(figure.alt.as_deref().is_some_and(|a| a.starts_with("A bar chart")));
}

#[test]
fn an_untagged_file_is_refused_as_untagged() {
    let bytes =
        std::fs::read(laminapdf_test_fixtures::fixtures_dir().join("reading-order/two-columns-ordered.pdf")).unwrap();
    let doc = Document::open(bytes, OpenOptions::default()).unwrap();
    let got = reflow(&doc, &CancelToken::new()).unwrap();
    assert_eq!(
        (got.available, got.reason.map(laminapdf_extract::ReflowRefusal::as_str)),
        (false, Some("untagged"))
    );
}
